import { relative } from "node:path";

/**
 * Computes a normalized POSIX relative import path from one folder to another.
 * Example:
 *   from "src/shared/router" to "src/pages" -> "../../pages"
 */
export function computeRelativeImport(fromDir: string, toDir: string): string {
    let rel = relative(fromDir, toDir).replace(/\\/g, "/");
    if (!rel.startsWith(".")) {
        rel = "./" + rel;
    }
    return rel;
}
