import { RouteItem } from "./types";

/**
 * Sorts routes deterministically by specificity:
 * 1. Root route ("/") at the top
 * 2. Static routes first (e.g. /products/new before /products/:id)
 * 3. Parameterized routes second
 * 4. Wildcard / Catch-all routes (/*)
 * 5. 404 fallback wildcard (*) at the very end
 */
export function sortRoutes(routes: RouteItem[]): RouteItem[] {
    return [...routes].sort((a, b) => {
        // Root path "/" goes to the top
        if (a.path === "/" && b.path !== "/") return -1;
        if (b.path === "/" && a.path !== "/") return 1;

        // Wildcard / 404 routes go to the end
        const aWildcard = a.path === "*" || a.path.includes("*");
        const bWildcard = b.path === "*" || b.path.includes("*");
        if (aWildcard && !bWildcard) return 1;
        if (!aWildcard && bWildcard) return -1;
        if (aWildcard && bWildcard) {
            // "/*" before pure "*"
            if (a.path !== "*" && b.path === "*") return -1;
            if (a.path === "*" && b.path !== "*") return 1;
        }

        // Compare segment by segment
        const aSegments = a.path.split("/").filter(Boolean);
        const bSegments = b.path.split("/").filter(Boolean);
        const maxLen = Math.max(aSegments.length, bSegments.length);

        for (let i = 0; i < maxLen; i++) {
            const segA = aSegments[i];
            const segB = bSegments[i];

            if (segA === undefined) return 1;
            if (segB === undefined) return -1;

            const isParamA = segA.startsWith(":");
            const isParamB = segB.startsWith(":");

            // Static segment takes precedence over dynamic parameter
            if (!isParamA && isParamB) return -1;
            if (isParamA && !isParamB) return 1;

            if (segA !== segB) {
                return segA.localeCompare(segB);
            }
        }

        return a.path.localeCompare(b.path);
    });
}
