import { resolveRoutePath } from "../resolver";
import { RouteItem } from "./types";
import { sortRoutes } from "./routeSorter";

/**
 * Generates an array of sorted, resolved route items from a list of scanned page files.
 */
export function generateRouter(files: string[], baseDir = ""): RouteItem[] {
    const rawRoutes = files.map(file => ({
        path: resolveRoutePath(file, baseDir),
        file
    }));

    return sortRoutes(rawRoutes);
}
